Certainly! Here's a complex smart contract designed for a decentralized voting system on the Ethereum blockchain. This contract incorporates features such as voter registration, vote casting, vote tallying, and time-locked voting periods. It ensures the security and integrity of the voting process.

```solidity
pragma solidity ^0.8.0;

contract VotingSystem {
    struct Voter {
        bool isRegistered;
        bool hasVoted;
        uint256 vote;
    }

    struct Proposal {
        string name;
        uint256 voteCount;
    }

    address public owner;
    mapping(address => Voter) public voters;
    Proposal[] public proposals;
    uint256 public votingPeriod;
    uint256 public endTime;

    modifier onlyOwner() {
        require(msg.sender == owner, "Only the owner can call this function.");
        _;
    }

    modifier onlyRegistered() {
        require(voters[msg.sender].isRegistered, "Only registered voters can call this function.");
        _;
    }

    modifier withinVotingPeriod() {
        require(block.timestamp <= endTime, "Voting period has ended.");
        _;
    }

    constructor(uint256 _votingPeriod, string[] memory _proposalNames) {
        owner = msg.sender;
        votingPeriod = _votingPeriod;
        for (uint256 i = 0; i < _proposalNames.length; i++) {
            proposals.push(Proposal({
                name: _proposalNames[i],
                voteCount: 0
            }));
        }
        endTime = block.timestamp + _votingPeriod;
    }

    function registerVoter(address _voter) public onlyOwner {
        require(!voters[_voter].isRegistered, "Voter is already registered.");
        voters[_voter].isRegistered = true;
    }

    function vote(uint256 _proposalIndex) public onlyRegistered withinVotingPeriod {
        require(!voters[msg.sender].hasVoted, "Voter has already voted.");
        voters[msg.sender].hasVoted = true;
        voters[msg.sender].vote = _proposalIndex;
        proposals[_proposalIndex].voteCount += 1;
    }

    function endVoting() public onlyOwner withinVotingPeriod {
        require(block.timestamp >= endTime, "Voting period has not ended yet.");
        // Additional logic to finalize voting and declare results can be added here.
    }

    function getProposalCount() public view returns (uint256) {
        return proposals.length;
    }

    function getProposal(uint256 _index) public view returns (string memory, uint256) {
        require(_index < proposals.length, "Proposal does not exist.");
        return (proposals[_index].name, proposals[_index].voteCount);
    }
}
```

This smart contract includes the following features:
1. **Voter Registration**: Only registered voters can participate in the voting process.
2. **Vote Casting**: Voters can cast their votes for proposals within the specified voting period.
3. **Proposal Management**: The contract supports multiple proposals and keeps track of their vote counts.
4. **Voting Period Control**: The owner can set the voting period and end it when necessary.
5. **Security and Access Control**: Use of modifiers to ensure that only authorized actions can be performed by the owner and registered voters.

This smart contract can be extended further to include additional features such as vote auditing, delegate voting, and more.

